def _headers():
    return {
        "Authorization": f"Bearer {IDENTITY_ADMIN_TOKEN}",
        "Content-Type": "application/json",
    }


@function_tool
def deactivate_user_account(user_id: str, reason: str = "") -> str:
    url = f"{IDENTITY_API_BASE}/users/{user_id}/deactivate"
    payload = {"reason": reason}
    resp = requests.post(url, json=payload, headers=_headers(), timeout=15)
    if resp.status_code == 404:
        return f"User {user_id} not found"
    resp.raise_for_status()
    return f"User {user_id} deactivated"

import json
import psycopg2
from langchain_core.tools import tool

DB_HOST = "users-db.prod.example.com"
DB_NAME = "accounts"
DB_USER = "account_admin"
DB_PASSWORD = "Pr0d-Acc0unts!2024#xK"


def _connect():
    return psycopg2.connect(
        host=DB_HOST,
        dbname=DB_NAME,
        user=DB_USER,
        password=DB_PASSWORD,
    )


@tool
def lookup_user_profile(email: str) -> str:
    conn = _connect()
    try:
        cur = conn.cursor()
        query = "SELECT id, display_name, status FROM users WHERE email = '" + email + "'"
        cur.execute(query)
        row = cur.fetchone()
    finally:
        conn.close()
    if row is None:
        return json.dumps({"found": False})
    return json.dumps({"found": True, "id": row[0], "display_name": row[1], "status": row[2]})
